using Terraplenagem.IFM;
int passed=0;void Test(string name,Action a){a();Console.WriteLine("OK "+name);passed++;}void Equal(double a,double b){if(Math.Abs(a-b)>1e-6)throw new Exception($"Esperado {b}, obtido {a}");}void Throws(Action a){try{a();}catch{return;}throw new Exception("Deveria rejeitar entrada.");}
Project P()=>new(){Origens=new(){new(){Nome="C1",Volume_banco_m3=10}},Destinos=new(){new(){Nome="A1",Volume_geometrico_m3=10}}};
Test("conversão banco/compactado e balanço",()=>{var p=P();p.Destinos[0].Volume_geometrico_m3=5;p.Destinos[0].Banco_por_geometrico=2;var r=Solver.Run(p);Equal(r.Distribuido_m3,10);Equal(r.Movimentos[0].Geometrico_m3,5);Equal(r.Pendencias.Count,0);});
Test("rota alternativa por arcos reversos (guloso falha)",()=>{var p=P();p.Origens[0].Volume_banco_m3=1;p.Origens.Add(new(){Nome="C2",Volume_banco_m3=1});p.Destinos[0].Volume_geometrico_m3=1;p.Destinos.Add(new(){Nome="A2",Volume_geometrico_m3=1});p.Rotas=new(){new(){Origem="C1",Destino="A1",DMT_override_m=1},new(){Origem="C1",Destino="A2",DMT_override_m=2},new(){Origem="C2",Destino="A1",DMT_override_m=2},new(){Origem="C2",Destino="A2",DMT_override_m=100}};var r=Solver.Run(p);Equal(r.Distribuido_m3,2);Equal(r.Objetivo,4);});
Test("qualidade e demanda não atendida",()=>{var p=P();p.Destinos[0].CBR_min_pct=20;var r=Solver.Run(p);Equal(r.Distribuido_m3,0);Equal(r.Pendencias.Count,2);});
Test("expansão, permeabilidade e categoria",()=>{foreach(var field in new[]{0,1,2}){var p=P();if(field==0)p.Destinos[0].Expansao_max_pct=0;if(field==1){p.Origens[0].Permeabilidade_m_s=.1;p.Destinos[0].Permeabilidade_max_m_s=.01;}if(field==2)p.Destinos[0].Categoria_exigida=2;Equal(Solver.Run(p).Distribuido_m3,0);}});
Test("ADME não recebe jazida",()=>{var p=P();p.Origens[0].Jazida=true;p.Destinos[0].ADME=true;Equal(Solver.Run(p).Distribuido_m3,0);});
Test("jazidas e ADME são reservas, sem transporte desnecessário",()=>{var p=P();p.Destinos[0].Progressiva_m=10;p.Origens.Add(new(){Nome="J1",Volume_banco_m3=10,Progressiva_m=200,Jazida=true});p.Destinos.Add(new(){Nome="ADME",Volume_geometrico_m3=10,Progressiva_m=200,ADME=true});var r=Solver.Run(p);Equal(r.Distribuido_m3,10);Equal(r.Movimentos.Single().Origem=="C1"?1:0,1);Equal(r.Objetivo,100);});
Test("solo para descarte não alimenta aterro",()=>{var p=P();p.Origens[0].SoDescarte=true;Equal(Solver.Run(p).Distribuido_m3,0);p.Destinos[0].ADME=true;Equal(Solver.Run(p).Distribuido_m3,10);});
Test("barreira e desvio explícito",()=>{var p=P();p.Destinos[0].Progressiva_m=100;p.Barreiras.Add(new(){Progressiva_m=50});Equal(Solver.Run(p).Distribuido_m3,0);p.Rotas.Add(new(){Origem="C1",Destino="A1",DMT_override_m=200});Equal(Solver.Run(p).Movimentos[0].DMT_m,200);});
Test("bloqueio prevalece sobre DMT",()=>{var p=P();p.Rotas.Add(new(){Origem="C1",Destino="A1",DMT_override_m=0,Bloqueado=true});Equal(Solver.Run(p).Distribuido_m3,0);});
Test("acessos, DMT limite e extraordinário",()=>{var p=P();p.Origens[0].Acesso_m=30;p.Destinos[0].Acesso_m=40;p.Destinos[0].Progressiva_m=100;p.Franquia_m=50;var r=Solver.Run(p);Equal(r.Movimentos[0].DMT_m,170);Equal(r.Movimentos[0].Extraordinario_m3_km,1.2);p.DMT_max_m=169;Equal(Solver.Run(p).Distribuido_m3,0);});
Test("faixas e custo",()=>{var p=P();p.Destinos[0].Progressiva_m=200;p.UsarCustos=true;p.Faixas[0].Custo_por_m3_banco=3;Equal(Solver.Run(p).Objetivo,30);p.Faixas.Clear();Throws(()=>Solver.Run(p));});
Test("cubação áreas médias e centroide triangular",()=>{var p=P();Cubation.Build(p,new(){new(){Progressiva_m=0,Corte_m2=0},new(){Progressiva_m=30,Corte_m2=6,Aterro_m2=4}},1.2,100,false);Equal(p.Origens[0].Volume_banco_m3,90);Equal(p.Origens[0].Progressiva_m,20);Equal(p.Destinos[0].Volume_geometrico_m3,60);});
Test("volume Civil informado não é recalculado",()=>{var p=P();Cubation.Build(p,new(){new(){Progressiva_m=0,Corte_m2=5},new(){Progressiva_m=30,Corte_m2=5,Corte_incremental_m3=123,VolumeInformado=true}},1,100,false);Equal(p.Origens[0].Volume_banco_m3,123);Equal(p.Origens[0].Progressiva_m,15);});
Test("compensação lateral conserva volumes e aceita saldo longitudinal zero",()=>{var p=P();Cubation.Build(p,new(){new(){Progressiva_m=0,Corte_m2=6,Aterro_m2=5},new(){Progressiva_m=20,Corte_m2=6,Aterro_m2=5}},1.2,100,true);Equal(p.CompensacaoLateral.Sum(x=>x.Banco_m3),120);Equal(p.CompensacaoLateral.Sum(x=>x.Aterro_geometrico_m3),100);Equal(p.Origens.Count,0);Equal(p.Destinos.Count,0);Equal(Solver.Run(p).Distribuido_m3,0);if(!Bruckner.Svg(p).Contains("<svg"))throw new Exception("Sem Bruckner.");});
Test("corte sem destino e aterro sem origem são pendências",()=>{var p=P();p.Destinos.Clear();Equal(Solver.Run(p).Pendencias.Single().Banco_m3,10);p=P();p.Origens.Clear();Equal(Solver.Run(p).Pendencias.Single().Banco_m3,10);});
Test("entradas inválidas",()=>{var p=P();p.Origens[0].Volume_banco_m3=double.NaN;Throws(()=>Solver.Run(p));p=P();p.Destinos[0].Banco_por_geometrico=0;Throws(()=>Solver.Run(p));p=P();p.Origens.Add(new(){Nome="c1"});Throws(()=>Solver.Run(p));Throws(()=>Files.ReadAreas("progressiva_m;corte_m2;aterro_m2\n0;1;0\n0;1;0").Tap(rows=>Cubation.Build(P(),rows,1,100,false)));});
Test("CSV decimal brasileiro e projeto JSON",()=>{var rows=Files.ReadAreas("progressiva_m;corte_m2;aterro_m2\n0;1,5;0\n20;1,5;0");Equal(rows[0].Corte_m2,1.5);var p=P();var path=Path.GetTempFileName();Files.Save(path,p);Equal(Solver.Run(Files.Load(path)).Distribuido_m3,10);File.Delete(path);});
// Compare optimizer to exhaustive integer transport solutions on small random networks.
Test("100 redes contra enumeração exaustiva",()=>{var rng=new Random(42);for(int k=0;k<100;k++){var p=P();p.Origens[0].Volume_banco_m3=2;p.Origens.Add(new(){Nome="C2",Volume_banco_m3=2});p.Destinos[0].Volume_geometrico_m3=2;p.Destinos.Add(new(){Nome="A2",Volume_geometrico_m3=2});var costs=new int[4];for(int i=0;i<4;i++){costs[i]=rng.Next(10);p.Rotas.Add(new(){Origem="C"+(i/2+1),Destino="A"+(i%2+1),DMT_override_m=costs[i]});}var expected=Enumerable.Range(0,3).Min(x=>x*costs[0]+(2-x)*costs[1]+(2-x)*costs[2]+x*costs[3]);Equal(Solver.Run(p).Objetivo,expected);}});
Console.WriteLine($"{passed} grupos de testes aprovados.");
if(args.Length>0){Directory.CreateDirectory(args[0]);var p=Project.Example();Files.Save(Path.Combine(args[0],"exemplo-ifm.json"),p);var r=Solver.Run(p);Files.Export(Path.Combine(args[0],"exemplo-distribuicao.csv"),r);Report.Html(Path.Combine(args[0],"exemplo-relatorio.html"),p,r);File.WriteAllText(Path.Combine(args[0],"exemplo-areas.csv"),"progressiva_m;corte_m2;aterro_m2\n0;10;0\n20;15;0\n40;5;2\n60;0;10\n80;0;15\n100;0;5\n");}
static class Extensions {public static T Tap<T>(this T x,Action<T> a){a(x);return x;}}
